True def transform(grid):
    out = [row[:] for row in grid]
    base = next(i for i, row in enumerate(grid) if any(v in (2, 8) for v in row))
    for c, v in enumerate(grid[base]):
        if v in (2, 8):
            height = 4 if v == 2 else 3
            for d in range(1, height + 1):
                r = base - d
                if r >= 0:
                    out[r][c] = v if d == height else 1
    return out
